from collections import deque, Counter
R,C=len(grid),len(grid[0])
marked={4:(2,10),8:(14,16),6:(21,27)}
# Identify orthogonally connected nonzero components, then map color markers.
seen=set(); comps=[]; comp_at={}
for r in range(R):
 for c in range(C):
  if grid[r][c]!=0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); cells=[]
   for p in q:
    rr,cc=p; cells.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=rr+dr,cc+dc
     if 0<=nr<R and 0<=nc<C and grid[nr][nc]!=0 and (nr,nc) not in seen:
      seen.add((nr,nc));q.append((nr,nc))
   i=len(comps); comps.append(cells)
   for p in cells: comp_at[p]=i
for color,p in marked.items(): print(color, 'component',comp_at[p], 'size',len(comps[comp_at[p]]))
labels={comp_at[p]:color for color,p in marked.items()}
out=[row[:] for row in grid]
allinter=[]
for cid,color in labels.items():
 pts=[]
 for r,c in comps[cid]:
  if all(0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]!=0 for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
   pts.append((r,c));out[r][c]=color
 allinter.append((color,pts))
print([(x,len(p),p) for x,p in allinter])
